self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE_NAME).then((cache) => cache.addAll(PRECACHE_URLS)));
});

const PRECACHE_PATHS = new Set(PRECACHE_URLS.map((path) => new URL(path, self.location).pathname));

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys
        .filter((key) => key.startsWith(RUNLOAD_CACHE_PREFIX) && key !== CACHE_NAME)
        .map((key) => caches.delete(key))))
      .then(() => caches.open(CACHE_NAME))
      .then((cache) => cache.keys().then((requests) => Promise.all(requests
        .filter((request) => !PRECACHE_PATHS.has(new URL(request.url).pathname))
        .map((request) => cache.delete(request)))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === "navigate") {
    event.respondWith(fetch(request).catch(() => caches.match("./index.html")));
    return;
  }

  if (!PRECACHE_PATHS.has(url.pathname)) return;
  event.respondWith(
    caches.open(CACHE_NAME).then((cache) => (
      cache.match(request, { ignoreSearch: true }).then((cached) => {
        if (cached) return cached;
        return fetch(request).then((response) => {
          if (response.ok && response.type === "basic") {
            const copy = response.clone();
            event.waitUntil(cache.put(request, copy));
          }
          return response;
        });
      })
    ))
  );
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") self.skipWaiting();
});

styles/interpretation-room.css:
.app-shell--immersive {
  padding-bottom: 0;
}

.app-shell--immersive .app-main {
  width: min(100%, 860px);
  padding-bottom: calc(32px + env(safe-area-inset-bottom));
}

.interpretation-room-header {
  position: sticky;
  top: 0;
  z-index: 45;
  display: grid;
  grid-template-columns: minmax(90px, 1fr) auto minmax(90px, 1fr);
  align-items: center;
  min-height: 56px;
  padding: max(8px, env(safe-area-inset-top)) clamp(14px, 3vw, 24px) 8px;
  border-bottom: 1px solid var(--color-line);
  background: color-mix(in srgb, var(--color-surface) 96%, transparent);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.interpretation-room-header__back {
  justify-self: start;
  color: var(--color-accent-strong);
  font-size: 13px;
  font-weight: 800;
  text-decoration: none;
}

.interpretation-room-header__title {
  justify-self: center;
  font-size: 15px;
  font-weight: 850;
}

.interpretation-room-header__spacer { min-width: 1px; }

.screen--interpretation-room,
.interpretation-room-view {
  display: grid;
  gap: 20px;
}

.interpretation-primary,
.interpretation-panel,
.interpretation-carry,
.interpretation-region-focus,
.interpretation-status-grid > div {
  border: 1px solid var(--color-line);
  border-radius: 18px;
  background: var(--color-surface);
}

.interpretation-primary {
  padding: clamp(18px, 4vw, 28px);
}

.interpretation-target {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.interpretation-target small,
.interpretation-carry small,
.interpretation-status-grid small,
.interpretation-view-head > p {
  color: var(--color-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .08em;
}

.interpretation-primary h1,
.interpretation-view-head h1 {
  margin: 5px 0 0;
  font-size: clamp(28px, 5vw, 40px);
  line-height: 1.15;
  letter-spacing: -.035em;
}

.interpretation-intro,
.interpretation-view-head > p:last-child {
  margin: 9px 0 0;
  color: var(--color-muted);
  line-height: 1.65;
}

.interpretation-summary-text {
  margin: 20px 0 0;
  font-size: clamp(16px, 2.5vw, 19px);
  line-height: 1.8;
  font-weight: 700;
}

.interpretation-primary .source-boundary,
.interpretation-panel .source-boundary {
  margin-top: 16px;
}

.interpretation-status-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.interpretation-status-grid > div {
  padding: 14px;
}

.interpretation-status-grid small,
.interpretation-status-grid strong { display: block; }
.interpretation-status-grid strong { margin-top: 5px; font-size: 13px; line-height: 1.55; }

.interpretation-region-focus-list { display: grid; gap: 10px; }
.interpretation-region-focus { padding: 15px 16px; }
.interpretation-region-focus h3,
.interpretation-region-focus p { margin: 0; }
.interpretation-region-focus p { margin-top: 6px; color: var(--color-muted); font-size: 13px; }

.interpretation-choice-section { display: grid; gap: 12px; }
.interpretation-choice-section h2 { margin: 0; font-size: 18px; }
.interpretation-choice-list { display: grid; gap: 9px; }

.interpretation-choice {
  min-height: 56px;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 4px 12px;
  padding: 13px 15px;
  border: 1px solid var(--color-line);
  border-radius: 14px;
  background: var(--color-surface);
  color: var(--color-ink);
  text-decoration: none;
}

.interpretation-choice strong { font-size: 14px; }
.interpretation-choice span { grid-column: 1; color: var(--color-muted); font-size: 12px; line-height: 1.45; }
.interpretation-choice i { grid-column: 2; grid-row: 1 / span 2; color: var(--color-accent-strong); font-style: normal; font-size: 20px; }
.interpretation-choice.is-disabled { opacity: .55; }

.interpretation-view-head { padding: 4px 0 8px; }
.interpretation-view-head > p { margin: 0; }
.interpretation-view-head > p:last-child { font-size: 13px; font-weight: 500; letter-spacing: 0; }

.interpretation-panel,
.interpretation-carry { padding: clamp(16px, 3vw, 22px); }
.interpretation-panel h2 { margin: 0; font-size: 18px; }
.interpretation-panel > p { line-height: 1.7; }
.interpretation-panel ul { padding-left: 1.4em; line-height: 1.7; }

.interpretation-table-wrap { overflow-x: auto; margin-top: 14px; }
.interpretation-table { width: 100%; min-width: 620px; border-collapse: collapse; font-size: 12px; }
.interpretation-table th,
.interpretation-table td { padding: 9px 8px; border-bottom: 1px solid var(--color-line); text-align: left; white-space: nowrap; }

.interpretation-evidence-item { border-top: 1px solid var(--color-line); }
.interpretation-evidence-item:first-of-type { margin-top: 12px; }
.interpretation-evidence-item summary { display: flex; justify-content: space-between; gap: 12px; padding: 13px 0; cursor: pointer; }
.interpretation-evidence-item > div { padding: 0 0 16px; }
.interpretation-evidence-item h3 { margin: 14px 0 4px; font-size: 13px; }
.interpretation-evidence-item p,
.interpretation-evidence-item li { font-size: 13px; line-height: 1.65; }
.interpretation-evidence-item li span { display: block; color: var(--color-muted); }
.interpretation-technical { color: var(--color-muted); font-size: 11px !important; }

.interpretation-carry p { margin: 6px 0 0; line-height: 1.65; }
.interpretation-inline-actions { display: flex; flex-wrap: wrap; gap: 8px; }

@media (max-width: 640px) {
  .interpretation-status-grid { grid-template-columns: 1fr; }
  .interpretation-target { align-items: flex-start; flex-direction: column; gap: 4px; }
  .interpretation-inline-actions { display: grid; }
  .interpretation-inline-actions .button { width: 100%; }
}

/* Keep wide detail tables inside the Room viewport; the table wrapper owns horizontal scrolling. */
.screen--interpretation-room,
.interpretation-room-view,
.interpretation-panel,
.interpretation-table-wrap {
  min-width: 0;
}

/* Stage 6: meaning-first explanation surfaces. */
.interpretation-primary--meaning h1 {
  margin-top: 8px;
  max-width: 34em;
  font-size: clamp(21px, 3.8vw, 30px);
  line-height: 1.55;
  letter-spacing: -.02em;
}

.interpretation-meaning-label,
.interpretation-section-head small,
.interpretation-simple-grid small,
.interpretation-visual-card__head small,
.interpretation-difference-card small,
.interpretation-boundary-card small {
  color: var(--color-accent-strong);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .08em;
}

.interpretation-meaning-label { margin: 22px 0 0; }

.interpretation-reasons {
  margin-top: 24px;
  padding-top: 18px;
  border-top: 1px solid var(--color-line);
}

.interpretation-reasons h2,
.interpretation-section-head h2 {
  margin: 0;
  font-size: 17px;
}

.interpretation-reasons ul {
  display: grid;
  gap: 8px;
  margin: 12px 0 0;
  padding-left: 1.35em;
}

.interpretation-reasons li {
  font-size: 13px;
  line-height: 1.65;
}

.interpretation-boundary-card {
  margin-top: 20px;
  padding: 14px 16px;
  border-radius: 14px;
  background: var(--color-paper);
}

.interpretation-boundary-card p {
  margin: 6px 0 0;
  font-size: 13px;
  line-height: 1.65;
}

.interpretation-explanation-section {
  display: grid;
  gap: 12px;
}

.interpretation-section-head {
  display: grid;
  gap: 4px;
}

.interpretation-view-choice-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.interpretation-view-choice {
  min-width: 0;
  min-height: 86px;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 14px;
  border: 1px solid var(--color-line);
  border-radius: 16px;
  background: var(--color-surface);
  color: var(--color-ink);
  text-decoration: none;
}

.interpretation-view-choice__icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 12px;
  background: var(--color-accent-soft);
  color: var(--color-accent-strong);
  font-size: 12px;
  font-weight: 900;
}

.interpretation-view-choice strong,
.interpretation-view-choice small {
  display: block;
}

.interpretation-view-choice strong { font-size: 14px; }
.interpretation-view-choice small { margin-top: 4px; color: var(--color-muted); font-size: 11px; line-height: 1.45; }
.interpretation-view-choice i { color: var(--color-accent-strong); font-style: normal; font-size: 20px; }

.interpretation-summary-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.interpretation-simple-grid,
.interpretation-difference-grid,
.interpretation-visual-stack {
  display: grid;
  gap: 12px;
}

.interpretation-simple-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.interpretation-simple-grid article,
.interpretation-visual-card,
.interpretation-difference-card {
  min-width: 0;
  padding: 17px;
  border: 1px solid var(--color-line);
  border-radius: 16px;
  background: var(--color-surface);
}

.interpretation-simple-grid p,
.interpretation-difference-card p,
.interpretation-visual-card p {
  margin: 8px 0 0;
  line-height: 1.7;
}

.interpretation-simple-grid p { font-size: 14px; }

.interpretation-visual-card__head h2,
.interpretation-difference-card h2 {
  margin: 4px 0 0;
  font-size: 18px;
}

.interpretation-comparison-svg {
  display: block;
  width: 100%;
  height: auto;
  margin-top: 12px;
  overflow: visible;
}

.interpretation-comparison-axis {
  stroke: var(--color-line);
  stroke-width: 4;
  stroke-linecap: round;
}

.interpretation-comparison-svg circle {
  fill: var(--color-surface);
  stroke-width: 4;
}

.interpretation-comparison-svg text {
  fill: var(--color-ink);
  font-size: 11px;
  font-weight: 800;
}

.interpretation-comparison-svg .marker-reference circle { stroke: var(--color-muted); }
.interpretation-comparison-svg .marker-previous circle { stroke: var(--color-line-strong, var(--color-muted)); }
.interpretation-comparison-svg .marker-current circle { stroke: var(--color-accent-strong); }
.interpretation-comparison-svg .marker-current text { fill: var(--color-accent-strong); }

.interpretation-difference-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.interpretation-difference-card strong {
  display: block;
  margin-top: 8px;
  color: var(--color-accent-strong);
}

.interpretation-difference-boundary { margin: 0; }
.interpretation-empty-note { margin: 0; color: var(--color-muted); }

@media (max-width: 640px) {
  .interpretation-view-choice-grid,
  .interpretation-simple-grid,
  .interpretation-difference-grid {
    grid-template-columns: 1fr;
  }

  .interpretation-summary-actions {
    display: grid;
  }

  .interpretation-summary-actions .button {
    width: 100%;
  }

  .interpretation-primary--meaning h1 {
    font-size: 20px;
    line-height: 1.6;
  }
}

/* Stage 7: deterministic guided dialogue. */
.interpretation-dialogue-thread {
  display: grid;
  gap: 14px;
}

.interpretation-dialogue-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--color-muted);
}

.interpretation-dialogue-meta small {
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .08em;
}

.interpretation-dialogue-meta span {
  font-size: 12px;
}

.interpretation-turn {
  min-width: 0;
  padding: clamp(17px, 3.5vw, 24px);
  border: 1px solid var(--color-line);
  border-radius: 18px;
  background: var(--color-surface);
}

.interpretation-turn--runload {
  border-left: 4px solid var(--color-accent-strong);
}

.interpretation-turn small {
  color: var(--color-accent-strong);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .08em;
}

.interpretation-turn p {
  margin: 8px 0 0;
  font-size: clamp(17px, 3vw, 22px);
  font-weight: 750;
  line-height: 1.7;
}

.interpretation-dialogue-boundary {
  margin: 0;
  padding: 0 2px;
  color: var(--color-muted);
  font-size: 12px;
  line-height: 1.6;
}

.interpretation-dialogue-prompt,
.interpretation-dialogue-followup {
  display: grid;
  gap: 10px;
}

.interpretation-dialogue-prompt h2,
.interpretation-dialogue-followup h2 {
  margin: 0;
  font-size: 17px;
}

.interpretation-dialogue-choice-list {
  display: grid;
  gap: 9px;
}

.interpretation-dialogue-choice {
  min-width: 0;
  min-height: 58px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 13px 15px;
  border: 1px solid var(--color-line);
  border-radius: 14px;
  background: var(--color-surface);
  color: var(--color-ink);
  text-decoration: none;
}

.interpretation-dialogue-choice strong,
.interpretation-dialogue-choice small {
  display: block;
}

.interpretation-dialogue-choice strong {
  font-size: 14px;
}

.interpretation-dialogue-choice small {
  margin-top: 4px;
  color: var(--color-muted);
  font-size: 11px;
  line-height: 1.45;
}

.interpretation-dialogue-choice i {
  color: var(--color-accent-strong);
  font-style: normal;
  font-size: 20px;
}

.interpretation-dialogue-followup {
  padding-top: 4px;
}

@media (max-width: 640px) {
  .interpretation-turn p {
    font-size: 17px;
  }
}

.interpretation-dialogue-context {
  padding: 12px 14px;
  border-left: 3px solid var(--color-line-strong, var(--color-muted));
  background: var(--color-paper);
}

.interpretation-dialogue-context small {
  color: var(--color-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .06em;
}

.interpretation-dialogue-context p {
  margin: 5px 0 0;
  font-size: 13px;
  line-height: 1.6;
}


/* Stage 8A: understanding-focused regional visual foundation. */
.interpretation-regional-visual {
  display: grid;
  grid-template-columns: minmax(126px, .42fr) minmax(0, 1fr);
  align-items: center;
  gap: 18px;
  margin-top: 12px;
}

.interpretation-body-locator {
  min-width: 0;
  margin: 0;
  display: grid;
  justify-items: center;
  gap: 8px;
}

.interpretation-body-locator-svg {
  display: block;
  width: min(100%, 156px);
  height: auto;
  overflow: visible;
}

.interpretation-body-silhouette > * {
  fill: var(--color-map-silhouette);
  stroke: var(--color-map-line);
  stroke-width: 2;
}

.interpretation-body-region {
  vector-effect: non-scaling-stroke;
  stroke-linejoin: round;
}

.interpretation-body-region.is-muted {
  fill: color-mix(in srgb, var(--color-map-silhouette) 70%, var(--color-accent-soft));
  stroke: var(--color-map-line);
  stroke-width: 1.5;
  opacity: .42;
}

.interpretation-body-region.is-focus {
  fill: color-mix(in srgb, var(--color-accent) 68%, var(--color-surface));
  stroke: var(--color-accent-strong);
  stroke-width: 3;
  opacity: 1;
  animation: interpretation-stage8-focus 280ms ease-out 1 both;
}

.interpretation-body-locator figcaption {
  display: grid;
  gap: 2px;
  text-align: center;
}

.interpretation-body-locator figcaption small {
  color: var(--color-muted);
  font-size: 10px;
}

.interpretation-body-locator figcaption strong {
  color: var(--color-accent-strong);
  font-size: 12px;
}

.interpretation-local-comparison {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.interpretation-visual-direction {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 9px;
}

.interpretation-visual-direction small {
  color: var(--color-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .04em;
}

.interpretation-visual-direction strong {
  color: var(--color-accent-strong);
  font-size: 13px;
}

.interpretation-visual-direction span {
  flex-basis: 100%;
  color: var(--color-muted);
  font-size: 10px;
  line-height: 1.45;
}

.interpretation-comparison-arrow {
  stroke: var(--color-accent-strong);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: interpretation-stage8-arrow-draw 320ms ease-out 80ms 1 forwards;
}

.interpretation-comparison-arrowhead {
  fill: var(--color-accent-strong);
  opacity: 0;
  animation: interpretation-stage8-arrowhead 160ms ease-out 360ms 1 forwards;
}

.interpretation-comparison-same-position circle {
  fill: none;
  stroke: var(--color-accent-strong);
  stroke-width: 2;
}

.interpretation-visual-card--regional .marker-current circle {
  animation: interpretation-stage8-target 280ms ease-out 300ms 1 both;
}

@keyframes interpretation-stage8-focus {
  0% {
    opacity: .62;
    filter: drop-shadow(0 0 0 transparent);
  }
  55% {
    opacity: 1;
    filter: drop-shadow(0 0 7px color-mix(in srgb, var(--color-accent) 58%, transparent));
  }
  100% {
    opacity: 1;
    filter: drop-shadow(0 0 0 transparent);
  }
}

@keyframes interpretation-stage8-arrow-draw {
  to { stroke-dashoffset: 0; }
}

@keyframes interpretation-stage8-arrowhead {
  to { opacity: 1; }
}

@keyframes interpretation-stage8-target {
  0%, 100% {
    stroke-width: 4;
    filter: drop-shadow(0 0 0 transparent);
  }
  58% {
    stroke-width: 6;
    filter: drop-shadow(0 0 6px color-mix(in srgb, var(--color-accent) 52%, transparent));
  }
}

html.ui-motion-reduced .interpretation-body-region.is-focus,
html.ui-motion-reduced .interpretation-comparison-arrow,
html.ui-motion-reduced .interpretation-comparison-arrowhead,
html.ui-motion-reduced .interpretation-visual-card--regional .marker-current circle {
  animation: none;
}

html.ui-motion-reduced .interpretation-comparison-arrow {
  stroke-dashoffset: 0;
}

html.ui-motion-reduced .interpretation-comparison-arrowhead {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .interpretation-body-region.is-focus,
  .interpretation-comparison-arrow,
  .interpretation-comparison-arrowhead,
  .interpretation-visual-card--regional .marker-current circle {
    animation: none;
  }

  .interpretation-comparison-arrow {
    stroke-dashoffset: 0;
  }

  .interpretation-comparison-arrowhead {
    opacity: 1;
  }
}

@media (max-width: 640px) {
  .interpretation-regional-visual {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .interpretation-body-locator-svg {
    width: 132px;
  }
}


/* Stage 8B: CURRENT_SHIFT_WITH_HISTORY understanding note. */
.interpretation-visual-insight {
  padding: 14px 16px;
  border-left: 3px solid var(--color-accent-strong);
  border-radius: 0 12px 12px 0;
  background: var(--color-accent-soft);
}

.interpretation-visual-insight small {
  color: var(--color-accent-strong);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .06em;
}

.interpretation-visual-insight p {
  margin: 5px 0 0;
  color: var(--color-ink);
  font-size: 13px;
  line-height: 1.65;
}


/* Stage 8B: separated condition context. */
.interpretation-condition-context {
  padding: 14px 16px;
  border: 1px solid var(--color-line);
  border-radius: 14px;
  background: var(--color-paper);
}

.interpretation-condition-context small {
  color: var(--color-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .06em;
}

.interpretation-condition-context p {
  margin: 5px 0 0;
  color: var(--color-ink);
  font-size: 14px;
  font-weight: 750;
  line-height: 1.55;
}

.interpretation-condition-context span {
  display: block;
  margin-top: 5px;
  color: var(--color-muted);
  font-size: 11px;
  line-height: 1.5;
}


/* Stage 8B: separate regional and ROF-J layers. */
.interpretation-layer-pair {
  display: grid;
  gap: 10px;
}

.interpretation-layer-lane {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.interpretation-layer-lane > small {
  color: var(--color-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .06em;
}

.interpretation-layer-separator {
  justify-self: center;
  padding: 4px 10px;
  border: 1px solid var(--color-line);
  border-radius: 999px;
  color: var(--color-muted);
  background: var(--color-paper);
  font-size: 10px;
  font-weight: 800;
}

.interpretation-layer-pair .interpretation-visual-card {
  width: 100%;
}


/* Stage 8B: repeated-observation count visual. */
.interpretation-repeated-layout {
  display: grid;
  grid-template-columns: minmax(126px, .42fr) minmax(0, 1fr);
  align-items: center;
  gap: 18px;
  margin-top: 12px;
}

.interpretation-repeated-count {
  min-width: 0;
  display: grid;
  gap: 14px;
}

.interpretation-repeat-current {
  display: flex;
  align-items: center;
  gap: 10px;
}

.interpretation-repeat-current span:last-child {
  display: grid;
  gap: 2px;
}

.interpretation-repeat-current small,
.interpretation-repeat-history small {
  color: var(--color-muted);
  font-size: 10px;
  font-weight: 800;
}

.interpretation-repeat-current strong {
  color: var(--color-accent-strong);
  font-size: 13px;
}

.interpretation-repeat-history {
  display: grid;
  gap: 7px;
}

.interpretation-repeat-dots {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.interpretation-repeat-dot {
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
  border: 2px solid var(--color-line);
  border-radius: 50%;
  background: var(--color-surface);
}

.interpretation-repeat-dot.is-match,
.interpretation-repeat-dot.is-current {
  border-color: var(--color-accent-strong);
  background: var(--color-accent-soft);
}

.interpretation-repeated-count > p {
  margin: 0;
  color: var(--color-ink);
  font-size: 13px;
  line-height: 1.65;
}

@media (max-width: 640px) {
  .interpretation-repeated-layout {
    grid-template-columns: 1fr;
    gap: 10px;
  }
}


/* Stage 8C: short guided reveal sequence. */
@keyframes interpretation-stage8-guided-reveal {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.interpretation-room-view--visual [data-reveal-step="explanation"] {
  animation: interpretation-stage8-guided-reveal 160ms ease-out 420ms 1 both;
}

.interpretation-room-view--visual [data-reveal-step="choices"] {
  animation: interpretation-stage8-guided-reveal 160ms ease-out 540ms 1 both;
}

html.ui-motion-reduced .interpretation-room-view--visual [data-reveal-step="explanation"],
html.ui-motion-reduced .interpretation-room-view--visual [data-reveal-step="choices"] {
  animation: none;
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .interpretation-room-view--visual [data-reveal-step="explanation"],
  .interpretation-room-view--visual [data-reveal-step="choices"] {
    animation: none;
    opacity: 1;
    transform: none;
  }
}


/* Stage 8D: current-shift self-management continuation. */
.interpretation-continuation {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
}

.interpretation-continuation > div {
  min-width: 0;
  padding: 13px 14px;
  border: 1px solid var(--color-line);
  border-radius: 13px;
  background: var(--color-surface);
}

.interpretation-continuation small {
  color: var(--color-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .05em;
}

.interpretation-continuation p {
  margin: 5px 0 0;
  color: var(--color-ink);
  font-size: 12px;
  line-height: 1.6;
}

@media (max-width: 640px) {
  .interpretation-continuation {
    grid-template-columns: 1fr;
  }
}

.interpretation-room-view--visual [data-reveal-step="continuation"] {
  animation: interpretation-stage8-guided-reveal 160ms ease-out 540ms 1 both;
}

.interpretation-room-view--visual [data-reveal-step="choices"] {
  animation-delay: 660ms;
}

html.ui-motion-reduced .interpretation-room-view--visual [data-reveal-step="continuation"] {
  animation: none;
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .interpretation-room-view--visual [data-reveal-step="continuation"] {
    animation: none;
    opacity: 1;
    transform: none;
  }
}

styles/prototype-mobile-parity.css:
/*
 * RunLoad mobile prototype parity layer.
 * Generated from the frozen prototype authority sources.
 * Screen DOM is progressively migrated to the prototype hierarchy.
 * Color aliases remain theme-driven; geometry follows the frozen prototype.
 */

.prototype-parity {
  --bg: var(--color-paper);
  --surface: var(--color-surface);
  --surface2: var(--color-surface-muted);
  --ink: var(--color-ink);
  --muted: var(--color-muted);
  --line: var(--color-line);
  --accent: var(--color-accent);
  --accent2: var(--color-accent-strong);
  --soft: var(--color-accent-soft);
  --thread: var(--color-model);
  --threadSoft: var(--color-model-soft);
  --model: var(--color-model);
  --model-soft: var(--color-model-soft);
  --violet: var(--color-model);
  --violetSoft: var(--color-model-soft);
  --warn: var(--color-attention);
  --warnSoft: var(--color-attention-soft);
  --weekend: var(--color-weekend-saturday);
  --shadow: var(--shadow-card);
  --paper: var(--color-paper);
  --s: var(--color-surface);
  --s2: var(--color-surface-muted);
  --a: var(--color-accent);
  --a2: var(--color-accent-strong);
  --accent-strong: var(--color-accent-strong);
  --accent-soft: var(--color-accent-soft);
  --focus: var(--color-focus);
  --shadow2: var(--shadow-card);
  --neutral: var(--color-neutral-soft);
  --danger: var(--color-danger);
  --dangerSoft: var(--color-danger-soft);
  --urgent: var(--color-attention);
  --urgentSoft: var(--color-attention-soft);
  --up: var(--color-attention);
  --flat: var(--color-muted);
  --down: var(--color-info);
  --gap: var(--color-neutral-soft);
  --ease: cubic-bezier(.2,.8,.2,1);
  min-width: 0;
}

/* Mobile is the approval target. Desktop receives its own parity pass later. */
@media (max-width: 54.99rem) {
  .app-main:has(> .prototype-parity) {
    width: 100%;
    margin: 0;
    padding: 0;
  }
  .prototype-parity {
    width: 100%;
    margin: 0 auto;
    padding-left: 14px;
    padding-right: 14px;
    padding-bottom: 42px;
  }
  .prototype-parity--home { padding-top: 24px; }
  .prototype-parity--record { padding-top: 20px; padding-bottom: 96px; }
  .prototype-parity--result { padding-top: 20px; }
  .prototype-parity--history { padding-top: 20px; }
  .prototype-parity--plan { padding-top: 20px; }
  .prototype-parity--simulation { padding-top: 18px; }
  .prototype-parity--course { padding-top: 18px; }
  .prototype-parity--gpx { padding-top: 18px; }
  .prototype-parity--consultation,
  .prototype-parity--support,
  .prototype-parity--reading,
  .prototype-parity--privacy,
  .prototype-parity--more,
  .prototype-parity--settings { padding-top: 24px; }
}



/* ===== Frozen prototype: home ===== */
.prototype-parity--home a,.prototype-parity--home button{font:inherit;-webkit-tap-highlight-color:transparent}
.prototype-parity--home a{text-decoration:none;color:inherit}
.prototype-parity--home button{touch-action:manipulation}
.prototype-parity--home .eyebrow{margin:0;color:var(--accent);font-size:9px;font-weight:900;letter-spacing:.16em}
.prototype-parity--home .page-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}
.prototype-parity--home .page-head h1{margin:4px 0 0;font-size:clamp(29px,4vw,38px);letter-spacing:-.045em}
.prototype-parity--home .page-head p:last-child{max-width:610px;margin:8px 0 0;color:var(--muted);font-size:10px;line-height:1.6}
.prototype-parity--home .date-badge{margin-top:5px;padding:7px 10px;border-radius:999px;background:var(--soft);color:var(--accent2);font-size:8px;font-weight:900;white-space:nowrap}
.prototype-parity--home .focus{margin-top:22px;border:1px solid color-mix(in srgb,var(--thread) 25%,var(--line));border-radius:26px;background:linear-gradient(145deg,color-mix(in srgb,var(--threadSoft) 82%,var(--surface)),var(--surface) 62%);box-shadow:var(--shadow);overflow:hidden}
.prototype-parity--home .focus-top{padding:17px 17px 15px;display:grid;grid-template-columns:42px minmax(0,1fr) auto;gap:11px;align-items:start}
.prototype-parity--home .marker{position:relative;width:42px;min-height:92px;display:flex;justify-content:center}
.prototype-parity--home .marker:before{content:"";position:absolute;top:17px;bottom:-26px;width:2px;background:linear-gradient(var(--thread),color-mix(in srgb,var(--thread) 15%,transparent))}
.prototype-parity--home .marker i{position:relative;z-index:1;width:16px;height:16px;margin-top:4px;border-radius:50%;background:var(--thread);box-shadow:0 0 0 7px color-mix(in srgb,var(--thread) 12%,transparent)}
.prototype-parity--home .focus-copy small{display:block;color:var(--muted);font-size:8px;font-weight:850}
.prototype-parity--home .focus-copy h2{margin:4px 0 0;font-size:13px;color:var(--thread)}
.prototype-parity--home .focus-text{margin:10px 0 0;font-size:20px;line-height:1.48;font-weight:850;letter-spacing:-.025em}
.prototype-parity--home .source{margin:10px 0 0;display:flex;align-items:center;gap:6px;flex-wrap:wrap;color:var(--muted);font-size:8px;font-weight:800}
.prototype-parity--home .source b{padding:4px 7px;border-radius:999px;background:var(--surface);border:1px solid var(--line);color:var(--accent2);font-size:7px}
.prototype-parity--home .carry{padding:6px 8px;border-radius:999px;background:var(--surface);border:1px solid color-mix(in srgb,var(--thread) 26%,var(--line));color:var(--thread);font-size:7px;font-weight:900;white-space:nowrap}
.prototype-parity--home .focus-actions{padding:13px 15px 15px;border-top:1px solid var(--line);background:color-mix(in srgb,var(--surface) 78%,transparent);display:grid;grid-template-columns:1fr auto;gap:8px}
.prototype-parity--home .primary,.prototype-parity--home .secondary{min-height:46px;border-radius:13px;font-weight:900;display:flex;align-items:center;justify-content:center}
.prototype-parity--home .primary{background:var(--accent);color:var(--color-on-accent);border:1px solid var(--accent);font-size:10px}
.prototype-parity--home .secondary{padding:0 13px;border:1px solid var(--line);background:var(--surface);color:var(--accent2);font-size:9px}
.prototype-parity--home .section{margin-top:30px}
.prototype-parity--home .section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:11px}
.prototype-parity--home .section-head small{display:block;font-size:8px;color:var(--muted);font-weight:900;letter-spacing:.12em}
.prototype-parity--home .section-head h2{margin:3px 0 0;font-size:18px}
.prototype-parity--home .section-head>a{color:var(--accent2);font-size:8px;font-weight:850}
.prototype-parity--home .grid{display:grid;gap:10px}
.prototype-parity--home .card{border:1px solid var(--line);border-radius:19px;background:var(--surface);box-shadow:0 7px 20px rgba(25,43,60,.06);padding:14px}
.prototype-parity--home .card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
.prototype-parity--home .card-head small,.prototype-parity--home .card-head strong{display:block}
.prototype-parity--home .card-head small{font-size:7px;color:var(--muted);font-weight:850}
.prototype-parity--home .card-head strong{margin-top:3px;font-size:14px}
.prototype-parity--home .pill{padding:5px 7px;border-radius:999px;background:var(--soft);color:var(--accent2);font-size:7px;font-weight:850}
.prototype-parity--home .metrics{margin-top:13px;display:grid;grid-template-columns:repeat(3,1fr);border-block:1px solid var(--line)}
.prototype-parity--home .metrics div{padding:10px 7px;text-align:center;border-right:1px solid var(--line)}
.prototype-parity--home .metrics div:last-child{border-right:0}
.prototype-parity--home .metrics strong,.prototype-parity--home .metrics small{display:block}
.prototype-parity--home .metrics strong{font-size:13px}
.prototype-parity--home .metrics small{margin-top:3px;font-size:7px;color:var(--muted)}
.prototype-parity--home .card-link{width:100%;min-height:42px;margin-top:11px;border:1px solid var(--line);border-radius:11px;background:var(--surface2);color:var(--accent2);display:flex;align-items:center;justify-content:space-between;padding:8px 10px;font-size:9px;font-weight:850}
.prototype-parity--home .card-actions{display:grid;gap:6px;margin-top:11px}
.prototype-parity--home .card-actions .card-link{margin-top:0}
.prototype-parity--home .card-link--understanding{border-color:transparent;background:transparent;color:var(--accent2);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 22%,transparent)}
.prototype-parity--home .plan{margin-top:12px;padding:11px;border-radius:13px;background:var(--soft)}
.prototype-parity--home .plan small,.prototype-parity--home .plan strong,.prototype-parity--home .plan span{display:block}
.prototype-parity--home .plan small{font-size:7px;color:var(--muted);font-weight:850}
.prototype-parity--home .plan strong{margin-top:3px;font-size:14px}
.prototype-parity--home .plan span{margin-top:4px;color:var(--muted);font-size:8px}
.prototype-parity--home .support{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.prototype-parity--home .support--two{grid-template-columns:repeat(2,1fr)}
.prototype-parity--home .support a,.prototype-parity--home .support button{min-height:76px;padding:11px;border:1px solid var(--line);border-radius:15px;background:var(--surface);color:var(--ink);text-align:left;display:flex;flex-direction:column;justify-content:space-between}
.prototype-parity--home .support span{font-size:16px;color:var(--accent)}
.prototype-parity--home .support strong{display:block;font-size:10px}
.prototype-parity--home .support small{display:block;margin-top:3px;color:var(--muted);font-size:7px}
.prototype-parity--home .toast.show{opacity:1;transform:translate(-50%,0)}
@media (max-width:620px){.prototype-parity--home .page-head p:last-child{font-size:9px}
.prototype-parity--home .focus-top{grid-template-columns:34px minmax(0,1fr);padding:15px 13px 13px;gap:8px}
.prototype-parity--home .marker{width:34px}
.prototype-parity--home .carry{grid-column:2;justify-self:start;margin-top:-2px}
.prototype-parity--home .focus-text{font-size:18px}
.prototype-parity--home .focus-actions{grid-template-columns:1fr 88px;padding:11px 12px 12px}
.prototype-parity--home .secondary{padding:0 8px}}
@media (max-width:360px){.prototype-parity--home .focus-text{font-size:17px}
.prototype-parity--home .focus-actions{grid-template-columns:1fr}
.prototype-parity--home .support a,.prototype-parity--home .support button{padding:9px}
.prototype-parity--home .support strong{font-size:9px}}
@media (min-width:880px){.prototype-parity--home .focus-top{padding:22px 23px 19px;grid-template-columns:48px minmax(0,1fr) auto}
.prototype-parity--home .marker{width:48px}
.prototype-parity--home .focus-text{font-size:25px;max-width:720px}
.prototype-parity--home .focus-actions{padding:14px 18px 17px;grid-template-columns:260px 150px;justify-content:start}
.prototype-parity--home .grid{grid-template-columns:1fr 1fr}}
@media (prefers-reduced-motion:reduce){.prototype-parity--home *:before,.prototype-parity--home *:after{transition-duration:.001ms!important;animation-duration:.001ms!important}}


/* ===== Frozen prototype: record ===== */
.prototype-parity--record button,.prototype-parity--record input,.prototype-parity--record select,.prototype-parity--record textarea{font:inherit}
.prototype-parity--record button,.prototype-parity--record a,.prototype-parity--record summary,.prototype-parity--record input,.prototype-parity--record select,.prototype-parity--record textarea{touch-action:manipulation}
.prototype-parity--record button,.prototype-parity--record summary,.prototype-parity--record .course-chip,.prototype-parity--record .linked-card{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
.prototype-parity--record button:focus-visible,.prototype-parity--record summary:focus-visible,.prototype-parity--record input:focus-visible,.prototype-parity--record select:focus-visible,.prototype-parity--record textarea:focus-visible{outline:3px solid color-mix(in srgb,var(--accent) 24%,transparent);outline-offset:2px}
.prototype-parity--record .eyebrow{margin:0;color:var(--accent);font-size:8px;font-weight:900;letter-spacing:.16em}
.prototype-parity--record .page-head{display:flex;align-items:flex-start;justify-content:space-between;padding:0 2px}
.prototype-parity--record .page-head h1{margin:4px 0 0;font-size:29px;letter-spacing:-.04em}
.prototype-parity--record .help-button{width:38px;height:38px;border-radius:50%;border:1px solid var(--line);background:var(--surface);color:var(--accent2);font-size:15px;font-weight:900;box-shadow:var(--shadow2)}
.prototype-parity--record .rof-compact{margin-top:18px;min-height:62px;padding:11px 12px;border:1px solid var(--line);border-radius:17px;background:linear-gradient(135deg,var(--surface),color-mix(in srgb,var(--accent-soft) 45%,var(--surface)));display:grid;grid-template-columns:1fr auto;align-items:center;gap:10px;box-shadow:var(--shadow2)}
.prototype-parity--record .rof-compact small,.prototype-parity--record .rof-compact strong,.prototype-parity--record .rof-compact span{display:block}
.prototype-parity--record .rof-compact small{font-size:7px;color:var(--accent);font-weight:900}
.prototype-parity--record .rof-compact strong{font-size:11px;margin-top:2px}
.prototype-parity--record .rof-compact span{font-size:8px;color:var(--muted);margin-top:3px}
.prototype-parity--record .rof-compact button{min-height:38px;padding:0 12px;border:1px solid var(--accent);border-radius:11px;background:var(--surface);color:var(--accent2);font-size:9px;font-weight:850}
.prototype-parity--record .core-card{margin-top:12px;padding:17px 15px 15px;border:1px solid var(--line);border-radius:24px;background:var(--surface);box-shadow:var(--shadow)}
.prototype-parity--record .core-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
.prototype-parity--record .stage-label{margin:0;font-size:8px;color:var(--accent);font-weight:900;letter-spacing:.08em}
.prototype-parity--record .core-heading h2{margin:3px 0 0;font-size:20px}
.prototype-parity--record .core-heading>span{padding:6px 8px;border-radius:999px;background:var(--accent-soft);color:var(--accent2);font-size:8px;font-weight:850}
.prototype-parity--record .activity-toggle{margin:17px 0 0;display:grid;grid-template-columns:1fr 1fr;gap:6px;background:var(--color-surface-muted);border:1px solid var(--line);border-radius:14px;padding:5px}
.prototype-parity--record .activity-toggle legend{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.prototype-parity--record .activity-toggle label{cursor:pointer}
.prototype-parity--record .activity-toggle input{position:absolute;opacity:0;pointer-events:none}
.prototype-parity--record .activity-toggle span{min-height:44px;display:grid;place-items:center;border:1px solid transparent;border-radius:10px;background:color-mix(in srgb,var(--surface) 38%,transparent);color:var(--muted);font-size:11px;font-weight:850;transition:border-color .12s ease,background .12s ease,color .12s ease,box-shadow .12s ease}
.prototype-parity--record .activity-toggle input:checked+span{border-color:var(--color-selection-border);background:var(--color-accent-soft);color:var(--accent2);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 18%,transparent),0 3px 10px color-mix(in srgb,var(--accent) 10%,transparent)}
.prototype-parity--record .activity-toggle input:focus-visible+span{outline:3px solid color-mix(in srgb,var(--color-focus) 38%,transparent);outline-offset:2px}
.prototype-parity--record .field{display:grid;gap:6px}
