@media (max-width: 54.99rem) {
  .app-shell {
    width: 100%;
    min-height: 100dvh;
    padding-bottom: calc(76px + env(safe-area-inset-bottom));
    background: var(--color-paper);
  }
  .app-header--desktop { display: none !important; }
  .prototype-mobile-topbar {
    position: sticky;
    top: 0;
    z-index: 40;
    height: 60px;
    padding: 11px clamp(15px, 3vw, 28px);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    border-bottom: 1px solid color-mix(in srgb, var(--color-line) 72%, transparent);
    background: color-mix(in srgb, var(--color-paper) 96%, transparent);
    backdrop-filter: blur(18px);
  }
  .prototype-mobile-topbar__brand {
    min-width: 0;
    color: inherit;
    text-decoration: none;
  }
  .prototype-mobile-topbar__brand strong,
  .prototype-mobile-topbar__brand small { display: block; }
  .prototype-mobile-topbar__brand strong { font-size: 17px; line-height: 1.15; }
  .prototype-mobile-topbar__brand small {
    margin-top: 2px;
    max-width: 55vw;
    overflow: hidden;
    color: var(--color-muted);
    font-size: 7px;
    font-weight: 850;
    letter-spacing: .14em;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .prototype-mobile-topbar__badge {
    flex: 0 0 auto;
    padding: 6px 9px;
    border: 1px solid var(--color-line);
    border-radius: 999px;
    background: var(--color-surface);
    color: var(--color-accent-strong);
    font-size: 7px;
    font-weight: 900;
    letter-spacing: .09em;
    white-space: nowrap;
  }
  .prototype-mobile-topbar--context {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  }
  .prototype-mobile-topbar--context > a {
    min-height: 44px;
    display: inline-flex;
    align-items: center;
    justify-self: start;
    padding: 0 4px;
    color: var(--color-accent-strong);
    font-size: 9px;
    font-weight: 900;
    text-decoration: none;
    white-space: nowrap;
  }
  .prototype-mobile-topbar--context > strong {
    justify-self: center;
    align-self: center;
    max-width: 48vw;
    overflow: hidden;
    font-size: 15px;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .prototype-mobile-topbar--context .prototype-mobile-topbar__actions {
    justify-self: end;
  }
  [data-context-back-duplicate] {
    display: none !important;
  }
  .primary-navigation {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 50;
    width: 100%;
    height: calc(76px + env(safe-area-inset-bottom));
    transform: none;
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 0;
    padding: 7px max(8px, env(safe-area-inset-left)) max(8px, env(safe-area-inset-bottom)) max(8px, env(safe-area-inset-right));
    border: 0;
    border-top: 1px solid var(--color-line);
    border-radius: 0;
    background: color-mix(in srgb, var(--color-surface) 93%, transparent);
    box-shadow: none;
    backdrop-filter: blur(18px);
  }
  .primary-navigation__link {
    min-width: 0;
    min-height: 0;
    display: grid;
    place-items: center;
    align-content: center;
    gap: 2px;
    padding: 4px 2px;
    border-radius: 12px;
    color: var(--color-muted);
    font-size: 8px;
    font-weight: 800;
    line-height: 1.1;
  }
  .primary-navigation__glyph {
    display: block;
    min-height: 19px;
    color: currentColor;
    font-size: 17px;
    font-weight: 800;
    line-height: 19px;
  }
  .primary-navigation__icon { display: none; }
  .primary-navigation__label { font-size: 8px; line-height: 1.1; }
  .primary-navigation__link.is-current {
    background: var(--color-accent-soft);
    color: var(--color-accent-strong);
  }
  .primary-navigation__link.is-disabled small { font-size: 6px; }
  .primary-navigation__link.is-disabled .primary-navigation__label { opacity: .75; }

  /* Keep transient application controls above the prototype navigation. */
  .pwa-update-notice,
  [data-pwa-update-notice] {
    bottom: calc(86px + env(safe-area-inset-bottom)) !important;
    z-index: 80 !important;
  }
}

/* ===== Shared segmented selection state ===== */
/*
 * Selected options use the same semantic theme tokens across prototype-parity
 * segmented controls. This keeps light/dark and accent themes consistent and
 * prevents a selected option from blending into its surrounding surface.
 */
.prototype-parity--record .activity-toggle input:checked + span,
.prototype-parity--result .view-toggle button.active,
.prototype-parity--result .sheet-tabs button.active,
.prototype-parity--history .history-mode button.active,
.prototype-parity--history .period-control button.active,
.prototype-parity--history .display-toggle button.active,
.prototype-parity--history .type-toggle button.active,
.prototype-parity--plan .seg button.active,
.prototype-parity--course .mode button.active,
.prototype-parity--reading .filters button.active,
.prototype-parity--settings .segment button.active {
  border-color: var(--color-selection-border);
  background: var(--color-selection-surface);
  color: var(--color-accent-strong);
  box-shadow:
    inset 0 0 0 1px var(--color-selection-border),
    0 3px 10px color-mix(in srgb, var(--color-accent) 10%, transparent);
}

/* ===== iOS resume scroll-surface resilience ===== */
@media (max-width:54.99rem){
  .prototype-parity--course .editor,
  .prototype-parity--record .subscreen,
  .prototype-parity--record .sheet,
  .prototype-parity--result .detail-screen,
  .prototype-parity--result .region-sheet,
  .prototype-parity--history .region-sheet,
  .prototype-parity--reading .sheet{
    -webkit-overflow-scrolling:touch;
  }
}


